<script lang="ts">
	import { onMount } from 'svelte';
	import { csrfHeaders, idempotencyKey } from '$lib/api/client';
	let p:any={preferred_channel:'whatsapp',fallback_channel:'email',payment_reminders_enabled:true,product_updates_enabled:false,quiet_start_hour:22,quiet_end_hour:7,timezone:'Africa/Lagos',version:1};
	let message='',busy=false,loading=true;
	async function load(){const r=await fetch('/api/v1/me/notification-preferences',{credentials:'include'});if(r.ok)p=(await r.json()).preferences;loading=false}
	async function save(){busy=true;message='';const r=await fetch('/api/v1/me/notification-preferences',{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({...p,expected_version:p.version})});const d=await r.json().catch(()=>({}));busy=false;if(r.ok){p=d.preferences;message='Your message choices were saved.'}else message=d.detail??'We could not save your message choices.'}
	onMount(load);
</script>
<svelte:head><title>Notification preferences — Kredit</title></svelte:head>
<main class="shell workspace settings"><p class="eyebrow">Settings / Messages</p><h1>Choose how Kredit reaches you.</h1><p class="lede">You can stop reminders and product news. We will still send important account and payment messages.</p>{#if message}<p class="notice" role="status">{message}</p>{/if}<section><h2>Where should we message you?</h2><label>Use this first<select disabled={loading} bind:value={p.preferred_channel}><option value="whatsapp">WhatsApp</option><option value="email">Email</option><option value="sms">SMS</option></select></label><label>If that does not work, use<select disabled={loading} bind:value={p.fallback_channel}><option value="email">Email</option><option value="sms">SMS</option><option value="whatsapp">WhatsApp</option></select></label><div class="hours"><label>Do not disturb from<input disabled={loading} type="number" min="0" max="23" bind:value={p.quiet_start_hour}/></label><label>Start messages again at<input disabled={loading} type="number" min="0" max="23" bind:value={p.quiet_end_hour}/></label></div><p>Use 24-hour time in Nigeria. An important safety or payment message may still come during this time.</p></section><section><h2>Messages you can stop</h2><label class="check"><input disabled={loading} type="checkbox" bind:checked={p.payment_reminders_enabled}/> Remind me about payments</label><label class="check"><input disabled={loading} type="checkbox" bind:checked={p.product_updates_enabled}/> Tell me about new Kredit features</label></section><button onclick={save} disabled={loading||busy||p.preferred_channel===p.fallback_channel}>{busy?'Saving…':'Save my choices'}</button></main>
<style>.settings{max-width:48rem}.settings h1{font-size:clamp(2.4rem,6vw,4.5rem);line-height:1}.settings section{display:grid;gap:.8rem;margin:1rem 0;padding:1.3rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}label{display:grid;gap:.35rem;font-weight:700}select,input,button{padding:.75rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}.hours{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.check{display:flex;align-items:center}.check input{width:1.2rem;height:1.2rem}button{background:var(--color-primary);color:white;font-weight:800}.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}@media(max-width:560px){.hours{grid-template-columns:1fr}}</style>
